import hmac
import hashlib
import time
import os
import secrets
import re
from typing import Optional, Dict, Tuple
from dataclasses import dataclass, field
from enum import Enum
import struct
import base64


class TokenType(Enum):
    SESSION = "session"
    API = "api"
    REFRESH = "refresh"


@dataclass
class RateLimitEntry:
    attempts: int = 0
    window_start: float = 0.0
    locked_until: float = 0.0


class SecureTokenStore:
    """Cryptographically secure token validation with rate limiting."""

    MAX_TOKEN_LENGTH = 512
    MIN_TOKEN_LENGTH = 32
    RATE_LIMIT_WINDOW = 60.0
    MAX_ATTEMPTS = 10
    LOCKOUT_DURATION = 300.0

    def __init__(self, secret_key: Optional[bytes] = None):
        self._secret = secret_key or secrets.token_bytes(64)
        self._tokens: Dict[str, Tuple[bytes, float, TokenType]] = {}
        self._rate_limits: Dict[str, RateLimitEntry] = {}
        self._revoked: set = set()
        self._nonce_cache: set = set()

    def _derive_key(self, context: str) -> bytes:
        """Derive a context-specific key using HKDF-like construction."""
        return hmac.new(
            self._secret,
            context.encode('utf-8'),
            hashlib.sha256
        ).digest()

    def generate_token(self, user_id: str, token_type: TokenType,
                       ttl_seconds: int = 3600) -> str:
        """Generate a cryptographically secure token."""
        if not user_id or not re.match(r'^[a-zA-Z0-9_\-]{1,128}$', user_id):
            raise ValueError("Invalid user_id format")

        if ttl_seconds <= 0 or ttl_seconds > 86400:
            raise ValueError("TTL must be between 1 and 86400 seconds")

        nonce = secrets.token_bytes(16)
        timestamp = struct.pack('>d', time.time())
        type_byte = struct.pack('B', list(TokenType).index(token_type))

        payload = nonce + timestamp + type_byte + user_id.encode('utf-8')

        key = self._derive_key(f"token:{token_type.value}")
        mac = hmac.new(key, payload, hashlib.sha256).digest()

        token_bytes = payload + mac
        token = base64.urlsafe_b64encode(token_bytes).decode('ascii')

        expiry = time.time() + ttl_seconds
        self._tokens[user_id] = (mac, expiry, token_type)

        return token

    def _constant_time_compare(self, a: bytes, b: bytes) -> bool:
        """Length-independent constant-time comparison to prevent timing attacks.

        Uses hmac.compare_digest for guaranteed constant-time behavior.
        Rejects empty inputs explicitly.
        """
        # Reject empty inputs - these should never be valid MACs
        if len(a) == 0 or len(b) == 0:
            return False

        # Reject if lengths don't match - MACs should be fixed size
        if len(a) != len(b):
            return False

        # Use Python's built-in constant-time comparison
        return hmac.compare_digest(a, b)

    def _check_rate_limit(self, client_id: str) -> bool:
        """Check if client has exceeded rate limit."""
        now = time.time()

        if client_id not in self._rate_limits:
            self._rate_limits[client_id] = RateLimitEntry()

        entry = self._rate_limits[client_id]

        if entry.locked_until > now:
            return False

        if now - entry.window_start > self.RATE_LIMIT_WINDOW:
            entry.attempts = 0
            entry.window_start = now

        entry.attempts += 1

        if entry.attempts > self.MAX_ATTEMPTS:
            entry.locked_until = now + self.LOCKOUT_DURATION
            return False

        return True

    def validate_token(self, token: str, user_id: str,
                       expected_type: TokenType,
                       client_id: str = "default") -> bool:
        """Validate a token with full security checks."""
        # Rate limiting
        if not self._check_rate_limit(client_id):
            return False

        # Input validation
        if not token or not isinstance(token, str):
            return False

        if not user_id or not re.match(r'^[a-zA-Z0-9_\-]{1,128}$', user_id):
            return False

        # Decode token
        try:
            token_bytes = base64.urlsafe_b64decode(token.encode('ascii'))
        except Exception:
            return False

        # Check token length bounds
        if len(token_bytes) < self.MIN_TOKEN_LENGTH or len(token_bytes) > self.MAX_TOKEN_LENGTH:
            return False

        # Check if token is revoked
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        if token_hash in self._revoked:
            return False

        # Verify stored token exists and hasn't expired
        if user_id not in self._tokens:
            return False

        stored_mac, expiry, stored_type = self._tokens[user_id]

        if time.time() > expiry:
            del self._tokens[user_id]
            return False

        if stored_type != expected_type:
            return False

        # Extract MAC from token (last 32 bytes)
        if len(token_bytes) < 32:
            return False

        provided_mac = token_bytes[-32:]

        # Constant-time comparison of MACs
        return self._constant_time_compare(provided_mac, stored_mac)

    def revoke_token(self, token: str) -> None:
        """Revoke a token by adding its hash to the revocation set."""
        if token and isinstance(token, str):
            token_hash = hashlib.sha256(token.encode()).hexdigest()
            self._revoked.add(token_hash)

    def validate_request_token(self, request_data: Dict) -> bool:
        """Validate an API request with anti-replay protection."""
        required_fields = ['token', 'user_id', 'nonce', 'timestamp']

        for field_name in required_fields:
            if field_name not in request_data:
                return False

        # Anti-replay: check nonce
        nonce = request_data['nonce']
        if not isinstance(nonce, str) or len(nonce) != 32:
            return False
        if not re.match(r'^[a-f0-9]{32}$', nonce):
            return False
        if nonce in self._nonce_cache:
            return False

        # Timestamp freshness check (5 minute window)
        try:
            req_time = float(request_data['timestamp'])
        except (ValueError, TypeError):
            return False

        if abs(time.time() - req_time) > 300:
            return False

        self._nonce_cache.add(nonce)

        # Limit nonce cache size
        if len(self._nonce_cache) > 100000:
            self._nonce_cache.clear()

        return self.validate_token(
            request_data['token'],
            request_data['user_id'],
            TokenType.API,
            client_id=request_data.get('client_id', 'default')
        )


def create_auth_middleware(secret: bytes = None):
    """Factory function for creating auth middleware."""
    store = SecureTokenStore(secret_key=secret)

    def middleware(request: Dict) -> Tuple[bool, str]:
        if 'authorization' not in request:
            return False, "Missing authorization"

        auth = request['authorization']
        if not auth.startswith('Bearer '):
            return False, "Invalid authorization scheme"

        token = auth[7:]
        user_id = request.get('user_id', '')

        if store.validate_token(token, user_id, TokenType.API):
            return True, "Authorized"

        return False, "Invalid or expired token"

    return store, middleware
